`define CYCLE_TIME 20.0
`define PAT_NUM 1000
`define RAND_SEED 54243

module PATTERN(
    clk, 
    rst_n, 
    in_valid,
    in_data_eq0,
    in_data_eq1,
    in_data_eq2,
    out_valid,
    out_data0, 
    out_data1,
    out_data2,
    exception
);

//---------------------------------------------------------------------
//   PORT DECLARATION
//---------------------------------------------------------------------
output logic clk; 
output logic rst_n;
output logic in_valid;
output logic [15:0] in_data_eq0;
output logic [15:0] in_data_eq1;
output logic [15:0] in_data_eq2;
input logic out_valid;
input logic signed [5:0] out_data0;
input logic signed [5:0] out_data1;
input logic signed [5:0] out_data2;
input logic [1:0] exception;

//================================================================
// clock
//================================================================
real CYCLE = `CYCLE_TIME;
initial begin
    clk = 1'b0;
    forever #(CYCLE/2.0) clk = ~clk;
end

//================================================================
// parameters & integer
//================================================================
int PATNUM = `PAT_NUM;
int SEED = `RAND_SEED;
int i, j, k;
int lat;
int pat_cnt;
int file_in, file_golden, fin, fout;
bit [2:0] input_data0, input_data1, input_data2;
bit [6:0] input_data3;
int golden0, golden1, golden2;
bit [1:0] golden_ex;
process main_pcs, check_pcs;

//================================================================
// initial
//================================================================
initial begin
    link_file;
    reset_task;
    fork : main_fork
        begin
            main_pcs = process::self();
            main_flow;
        end
        begin
            check_pcs = process::self();
            check_out_valid;
        end
    join_any
    disable main_fork;
    $finish;
end

//================================================================
// tasks
//================================================================
task main_flow; begin
    repeat (PATNUM) begin
        repeat($urandom_range(5,10)) @(negedge clk);
        send_input;
        wait_out_valid;
        check_ans;
        check_out_valid_drop;
        pass_single_pattern;
        pat_cnt = pat_cnt + 1;
    end
    YOU_PASS;
    $finish;
end endtask

task check_out_valid; begin
    forever begin
        @(negedge clk);
        if(out_valid === 1'b1 && in_valid === 1'b1) begin
            main_pcs.kill();
            fail; 
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            $display ("                                                       FAIL!                                                            ");
            $display ("                                        output should be 0 when in_valid is 1                                                         ");
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            #(3*CYCLE);
            $finish;
        end
        if(out_valid !== 1'b1 && (out_data0 !== 6'h0 || out_data1 !== 6'h0 || out_data2 !== 6'h0 || exception !== 2'b00)) begin
            main_pcs.kill();
            fail; 
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            $display ("                                                       FAIL!                                                            ");
            $display ("                                        output should be 0 when out_valid is LOW                                                            ");
            $display ("                                              Your out_valid:     %1b                                                            ", out_valid);
            $display ("                                              Your out_data0: %5d                                                            ", out_data0);
            $display ("                                              Your out_data1: %5d                                                            ", out_data1);
            $display ("                                              Your out_data2: %5d                                                            ", out_data2);
            $display ("                                              Your exception:    %2b                                                            ", exception);
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            #(3*CYCLE);
            $finish;
        end
    end
end endtask

task link_file; begin
    file_in = $fopen("../00_TESTBED/equations.txt", "r");
    file_golden = $fopen("../00_TESTBED/answers.txt", "r");
end endtask

task pass_single_pattern; begin
    case($urandom_range(0,4))
        0: $display("\033[38;5;10mPATTERN NO.%5d PASS!!\033[0m", pat_cnt);
        1: $display("\033[38;5;11mPATTERN NO.%5d PASS!!\033[0m", pat_cnt);
        2: $display("\033[38;5;12mPATTERN NO.%5d PASS!!\033[0m", pat_cnt);
        3: $display("\033[38;5;13mPATTERN NO.%5d PASS!!\033[0m", pat_cnt);
        4: $display("\033[38;5;208mPATTERN NO.%5d PASS!!\033[0m", pat_cnt);
    endcase
    
end endtask

task reset_task; begin
	rst_n = 1'b1; 
    
	force clk = 1'b0;
	#(2.0*CYCLE); rst_n = 1'b0;
	#(2.5*CYCLE); 
    
	if(out_valid !== 1'b0 | out_data0 !== 6'h0 | out_data1 !== 6'h0 | out_data2 !== 6'h0 | exception !== 2'b00) begin
		fail; 
		$display ("--------------------------------------------------------------------------------------------------------------------------------------------");
		$display ("                                                     RESET FAIL!                                                            ");
        $display ("                                                   out_valid :     %1b                                                            ", out_valid);
        $display ("                                                   out_data0 : %5d                                                            ", out_data0);
        $display ("                                                   out_data1 : %5d                                                            ", out_data1);
        $display ("                                                   out_data2 : %5d                                                            ", out_data2);
        $display ("                                                   exception :    %2b                                                            ", exception);
		$display ("--------------------------------------------------------------------------------------------------------------------------------------------");
		#(3*CYCLE);
		$finish;
	end

	rst_n = 1'b1; 
	in_valid = 1'b0; 
    in_data_eq0 = 'x;
    in_data_eq1 = 'x;
    in_data_eq2 = 'x;
    pat_cnt = 0;
	#(3.5*CYCLE); release clk; 
    repeat(4) @(negedge clk);
end endtask

task send_input; begin
    @(negedge clk);
    in_valid = 1'b1;
    fin = $fscanf(file_in, "%d %d %d %d", input_data0, input_data1, input_data2, input_data3);
    in_data_eq0 = {input_data3, input_data2, input_data1, input_data0};
    fin = $fscanf(file_in, "%d %d %d %d", input_data0, input_data1, input_data2, input_data3);
    in_data_eq1 = {input_data3, input_data2, input_data1, input_data0};
    fin = $fscanf(file_in, "%d %d %d %d", input_data0, input_data1, input_data2, input_data3);
    in_data_eq2 = {input_data3, input_data2, input_data1, input_data0};

    @(negedge clk);
	in_valid = 1'b0; 
    in_data_eq0 = 'x;
    in_data_eq1 = 'x;
    in_data_eq2 = 'x;

end endtask

task wait_out_valid; begin
    lat = 0;
    while(out_valid !== 1) begin
        lat = lat + 1;
        if (lat > 50) begin
            fail; 
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            $display ("                                           TIMEOUT! Latency over 50 cycles                                                            ");
            $display ("                                               Waiting for out_valid                                                            ");
            $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
            #(3*CYCLE);
            $finish;
        end
        @(negedge clk);
    end
end endtask

task check_ans; begin
    golden_ex = 0;
    fout = $fscanf(file_golden, "%d", golden0);
    if(golden0 === 9999) begin
        golden_ex = 1;
        check_ex;
    end else if(golden0 === 9998) begin
        golden_ex = 2;
        check_ex;
    end else begin
        fout = $fscanf(file_golden, "%d %d", golden1, golden2);
        check_ex;
        check_data;
    end
end endtask
    
task check_ex; begin
    #(0.1*CYCLE);
    if(exception !== golden_ex) begin
        fail; 
        $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
        $display ("                                                     PATTERN NO. %5d FAIL!                                                            ", pat_cnt);
        $display ("                                                        Incorrect exception                                                            ");
        $display ("                                                       Expected exception: %2b                                                            ", golden_ex);
        $display ("                                                        Your exception: %2b                                                            ", exception);
        $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
        #(3*CYCLE);
        $finish;
    end
end endtask

task check_data; begin
    #(0.1*CYCLE);
    if(out_data0 !== golden0 || out_data1 !== golden1 || out_data2 !== golden2) begin
        fail; 
        $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
        $display ("                                                     PATTERN NO. %5d FAIL!                                                            ", pat_cnt);
        $display ("                                                        Incorrect output data                                                            ");
        $display ("                                                          Expected out_data0: %5d                                                            ", golden0);
        $display ("                                                        Your out_data0: %5d                                                            ", out_data0);
        $display ("                                                          Expected out_data1: %5d                                                            ", golden1);
        $display ("                                                        Your out_data1: %5d                                                            ", out_data1);
        $display ("                                                          Expected out_data2: %5d                                                            ", golden2);
        $display ("                                                        Your out_data2: %5d                                                            ", out_data2);
        $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
        #(3*CYCLE);
        $finish;
    end

end endtask

task check_out_valid_drop; begin
    @(negedge clk);
    if(out_valid !== 1'b0) begin
        fail; 
        $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
        $display ("                                                       FAIL!                                                            ");
        $display ("                                        out_valid should be HIGH for only 1 cycle                                                            ");
        $display ("--------------------------------------------------------------------------------------------------------------------------------------------");
        #(3*CYCLE);
        $finish;
    end
end endtask

